    # Register error handlers for different status codes
    @app.error(401)
    def handle_401(error):
        return {"error": "Unauthorized", "message": "Please provide valid credentials"}

    @app.error(404)
    def handle_404(error):
        return {"error": "Not Found", "message": "The requested resource was not found"}

    @app.error(500)
    def handle_500(error):
        return {"error": "Internal Server Error", "message": "Something went wrong"}

    # Routes that trigger different errors
    @app.route('/unauthorized')
    def unauthorized():
        abort(401)

    @app.route('/notfound')
    def notfound():
        abort(404)

    @app.route('/servererror')
    def servererror():
        abort(500)

    print("=== Error Handler Integration Test ===")

